58	function fmtUptime(seconds: number): string {
59	  if (!seconds || seconds <= 0) return "—";
60	  const d = Math.floor(seconds / 86400);
61	  const h = Math.floor((seconds % 86400) / 3600);
62	  const m = Math.floor((seconds % 3600) / 60);
63	  return d > 0 ? `${d}d ${h}h ${m}m` : h > 0 ? `${h}h ${m}m` : `${m}m`;
64	}
