75	export default async function ServerPage({
76	  params,
77	  searchParams,
78	}: {
79	  params: Promise<{ id: string }>;
80	  searchParams: Promise<{ tab?: string }>;
81	}) {
82	  const [{ id }, { tab }] = await Promise.all([params, searchParams]);
83	  const user = await requireUser();
84	  const server = await db.server.findUnique({
85	    where: { id },
86	    include: {
87	      plan: true,
88	      osTemplate: true,
89	      project: true,
90	      portForwards: { orderBy: { publicPort: "asc" } },
91	      firewallRules: { orderBy: [{ position: "asc" }, { createdAt: "asc" }] },
92	      jobs: { orderBy: { createdAt: "desc" }, take: 20 },
93	      dedicatedIp: true,
94	      node: true,
95	      // Needed to price a renewal correctly: a game server bills its game plan's
96	      // flat price, not the base VPS plan's term price.
97	      gamePlan: true,
98	    },
99	  });
100	  if (!server || (server.userId !== user.id && user.role !== "ADMIN")) notFound();
101	
102	  // Root password may be stored encrypted-at-rest (rootPasswordEnc); resolve the
103	  // display value through the decrypt fallback (legacy plaintext rows still work).
104	  const rootPassword = serverRootPassword(server);
105	
106	  const [projects, activePlans, osTemplates, extraDiskPriceCents, backupPlusCents, annualPct] = await Promise.all([
107	    db.project.findMany({ where: { userId: server.userId }, orderBy: { name: "asc" } }),
108	    db.plan.findMany({ where: { active: true }, orderBy: { sortOrder: "asc" } }),
109	    db.osTemplate.findMany({
110	      where: { active: true, category: "PLAIN_OS" },
111	      orderBy: [{ sortOrder: "asc" }, { name: "asc" }],
112	    }),
113	    extraDiskPerGbCents(),
114	    backupPlusMonthlyCents(),
115	    // Live annual discount — feeds the "Renew now" quote below AND the resize
116	    // pickers, so an annual server's renewal/upgrade/downgrade all price against the
117	    // same rate it was sold at.
118	    annualDiscountPct(),
119	  ]);
120	
121	  // VAT/GST for the SERVER OWNER (Finding 1), resolved from their billing country.
122	  const owner =
123	    server.userId === user.id ? user : (await db.user.findUnique({ where: { id: server.userId } })) ?? user;
124	  const renewTaxCtx = await taxContextForUser(owner);
125	
126	  // What "Renew now" will actually charge, priced through the SAME function the
127	  // action charges through, so the button cannot quote one figure and take
128	  // another. See lib/renewal-quote.ts for the incident.
129	  const renewQuote = renewalQuote(
130	    {
131	      termMonths: server.termMonths,
132	      extraDiskGB: server.extraDiskGB,
133	      plan: { name: server.plan.name, priceCents: server.plan.priceCents },
134	      // A game server is sold at its game plan's flat price, NOT the base VPS
135	      // plan it happens to be built on. Omitting this quoted an $8.99 renewal for
136	      // a $4.99 product.
137	      gamePlan: server.gamePlan
138	        ? { name: server.gamePlan.name, priceCents: server.gamePlan.priceCents, termMonths: server.gamePlan.termMonths }
139	        : null,
140	      dedicatedIp: server.dedicatedIp,
141	      backupTier: server.backupTier,
142	    },
143	    {
144	      ipMonthlyCents: server.dedicatedIp ? await dedicatedIpMonthlyCents() : 0,
145	      extraDiskPerGbCents: extraDiskPriceCents,
146	      backupPlusCents,
147	      annualDiscountPct: annualPct,
148	      // VAT/GST for the owner (Finding 1): the "Renews at $X" figure and the Renew
149	      // now quote are tax-inclusive, matching what renewNow charges.
150	      taxRatePercent: renewTaxCtx.ratePercent,
151	    },
152	  );
153	
154	  // The server's REAL disk: plan allowance + any separately-purchased extra disk.
155	  // Every disk figure on this page uses this, never `plan.diskGB` on its own.
156	  const totalDiskGB = effectiveDiskGB(server.plan.diskGB, server.extraDiskGB);
157	
158	  const publicIp = process.env.PUBLIC_IP ?? "";
159	  const transitional = ["PENDING", "PROVISIONING", "REINSTALLING", "DELETING"].includes(server.status);
160	  const busy =
161	    transitional || server.jobs.some((j) => j.status === "QUEUED" || j.status === "RUNNING");
162	  const steady = ["RUNNING", "STOPPED"].includes(server.status);
163	
164	  let live: LiveStats = null;
165	  let snapshots: { name: string; snaptime?: number; description?: string }[] = [];
166	  let backups: { volid: string; ctime?: number; size?: number }[] = [];
167	  let pveUnavailable = false;
168	
169	  if (server.vmid && steady) {
170	    const results = await Promise.allSettled([
171	      vmStatus(server.vmid),
172	      listSnapshots(server.vmid),
173	      listBackups(server.vmid),
174	    ]);
175	    if (results[0].status === "fulfilled") live = results[0].value as LiveStats;
176	    if (results[1].status === "fulfilled") snapshots = results[1].value as typeof snapshots;
177	    if (results[2].status === "fulfilled") backups = results[2].value as typeof backups;
178	    pveUnavailable = results.some((r) => r.status === "rejected");
179	  }
180	
181	  // Dedicated-IP servers connect straight to their own public IP on port 22; NAT
182	  // servers use the platform public IP + the forwarded SSH port. (A dedicated
183	  // server has sshPort=null, which previously fell through to "provisioning…".)
184	  const sshCommand = server.dedicatedIp
185	    ? `ssh root@${server.dedicatedIp.address}`
186	    : server.sshPort
187	      ? `ssh root@${publicIp} -p ${server.sshPort}`
188	      : null;
189	
190	  // Single-item terminal list for this server — connect string computed the
191	  // same way as the Claude Code hub (dedicated IP → own IP, else NAT SSH port).
192	  const terminalServers = [
193	    {
194	      id: server.id,
195	      hostname: server.hostname,
196	      connect: server.dedicatedIp
197	        ? `ssh root@${server.dedicatedIp.address}`
198	        : `ssh -p ${server.sshPort ?? 22} root@${publicIp || "YOUR_SERVER_IP"}`,
199	    },
200	  ];
201	
202	  // SFTP/SSH connection details: dedicated-IP servers connect to their own IP on
203	  // port 22; NAT servers use the platform public IP + the forwarded SSH port.
204	  const dedicated = !!server.dedicatedIp;
205	  const sftpHost = dedicated ? server.dedicatedIp!.address : publicIp || null;
206	  const sftpPort = dedicated ? 22 : server.sshPort;
207	  const isGameServer = GAME_FAMILIES.includes(server.osTemplate.family as GameFamily);
208	
209	  // Per-game customization (only for game servers with a customization schema).
210	  const gameFamily = familyFor(server);
211	  const gameSchema = schemaFor(gameFamily);
212	  const gameVariant =
213	    gameSchema && server.gameVariant && isValidVariant(gameFamily!, server.gameVariant)
214	      ? server.gameVariant
215	      : gameSchema?.defaultVariant ?? "";
216	  const gameValidated = gameFamily
217	    ? validateConfig(gameFamily, (server.gameConfig as Record<string, unknown> | null) ?? {})
218	    : null;
219	  const gameValues = gameValidated && gameValidated.ok ? gameValidated.values : {};
220	
221	  /* ---------- Tab: Overview ---------- */
222	  const overview = (
223	    // `grid-cols-1` is load-bearing below `md`. With no base template the browser
224	    // creates an IMPLICIT `auto` track, sized to min-content and unclampable: at
225	    // 390px the rehearsal measured it at 530px — the `ssh root@… -p …` <code> and
226	    // the SFTP/SSH credentials are unbreakable strings — scrolling the whole page
227	    // 156px sideways. `grid-cols-1` compiles to `repeat(1, minmax(0, 1fr))`, the
228	    // same minmax `md:grid-cols-2` already applies, which is why desktop was fine.
229	    <div className="grid grid-cols-1 gap-6 md:grid-cols-2">
230	      <div className="card">
231	        <h2 className="mb-4 font-semibold">Access</h2>
232	        <dl className="space-y-3 text-sm">
233	          <div>
234	            <dt className="text-slate-400">SSH command</dt>
235	            <dd className="mt-1 flex items-center gap-2">
236	              {/* min-w-0 + overflow-x-auto so a long/IPv6 SSH command scrolls
237	                  inside its own box instead of widening the card at 390px —
238	                  parity with the hardened SftpAccess command strings. */}
239	              <code className="min-w-0 flex-1 overflow-x-auto whitespace-nowrap rounded-lg border border-white/10 bg-navy-950/80 px-2.5 py-1.5 font-mono text-xs">
240	                {sshCommand ?? "provisioning…"}
241	              </code>
242	              {sshCommand && <CopyText text={sshCommand} />}
243	            </dd>
244	          </div>
245	          <div className="flex items-center justify-between">
246	            <dt className="text-slate-400">Root password</dt>
247	            <dd>
248	              {rootPassword ? (
249	                <RevealPassword password={rootPassword} />
250	              ) : (
251	                <span className="text-slate-500">—</span>
252	              )}
253	            </dd>
254	          </div>
255	          <div className="flex items-center justify-between">
256	            <dt className="text-slate-400">{dedicated ? "Public IP" : "Private IP"}</dt>
257	            <dd className="font-mono text-xs">{(dedicated ? server.dedicatedIp!.address : server.ipAddress) ?? "—"}</dd>
258	          </div>
259	        </dl>
260	        <div className="divider" />
261	        <div className="flex flex-wrap items-center justify-between gap-2">
262	          <p className="text-xs text-slate-500">
263	            Lost access or rotating credentials? Generate a fresh root password.
264	          </p>
265	          <ResetPasswordButton serverId={server.id} disabled={busy || !steady} />
266	        </div>
267	      </div>
268	
269	      <SftpAccess
270	        host={sftpHost}
271	        port={sftpPort}
272	        password={rootPassword}
273	        dedicated={dedicated}
274	      />
275	
276	      {isGameServer && (
277	        <div className="md:col-span-2">
278	          <GameAutoUpdate
279	            serverId={server.id}
280	            gameName={server.osTemplate.name}
281	            autoUpdate={server.autoUpdate}
282	            canUpdate={server.status === "RUNNING"}
283	            busy={busy}
284	          />
285	        </div>
286	      )}
287	
288	      {server.gamePlanId && gameSchema && (
289	        <div className="md:col-span-2">
290	          <GameSettings
291	            serverId={server.id}
292	            schema={gameSchema}
293	            variant={gameVariant}
294	            values={gameValues}
295	            disabled={busy || !steady}
296	          />
297	        </div>
298	      )}
299	
300	      <div className="card">
301	        <h2 className="mb-4 font-semibold">Live stats</h2>
302	        {live ? (
303	          <div className="space-y-4 text-sm">
304	            <div>
305	              <div className="mb-1.5 flex justify-between">
306	                <span className="text-slate-400">CPU</span>
307	                <span className="font-semibold">{((live.cpu ?? 0) * 100).toFixed(1)}%</span>
308	              </div>
309	              <MeterBar value={(live.cpu ?? 0) * 100} max={100} />
310	            </div>
311	            <div>
312	              <div className="mb-1.5 flex justify-between">
313	                <span className="text-slate-400">Memory</span>
314	                <span className="font-semibold">
315	                  {fmtBytes(live.mem ?? 0)} / {fmtBytes(live.maxmem ?? 0)}
316	                </span>
317	              </div>
318	              <MeterBar value={live.mem ?? 0} max={live.maxmem ?? 1} color="#3b82f6" />
319	            </div>
320	            <div className="flex justify-between">
321	              <span className="text-slate-400">Uptime</span>
322	              <span className="font-semibold">{fmtUptime(live.uptime ?? 0)}</span>
323	            </div>
324	            <div className="flex justify-between">
325	              <span className="text-slate-400">Network I/O</span>
326	              <span className="font-mono text-xs">
327	                {fmtBytes(live.netin ?? 0)} in · {fmtBytes(live.netout ?? 0)} out
328	              </span>
329	            </div>
330	          </div>
331	        ) : (
332	          <p className="text-sm text-slate-400">
333	            {pveUnavailable
334	              ? "Hypervisor is briefly unavailable — stats will reappear shortly."
335	              : "Live stats appear once the server is provisioned."}
336	          </p>
337	        )}
338	      </div>
339	
340	      <div className="card">
341	        <h2 className="mb-4 font-semibold">Configuration</h2>
342	        <dl className="space-y-2.5 text-sm">
343	          <div className="flex justify-between">
344	            <dt className="text-slate-400">Plan</dt>
345	            <dd>
346	              {server.plan.name} — {server.plan.cpuCores} vCPU / {server.plan.ramMB / 1024} GB /{" "}
347	              {totalDiskGB} GB NVMe
348	              {server.extraDiskGB > 0 && (
349	                <span className="block text-xs text-slate-500">
350	                  {server.plan.diskGB} GB plan + {server.extraDiskGB} GB added storage
351	                </span>
352	              )}
353	            </dd>
354	          </div>
355	          <div className="flex justify-between">
356	            <dt className="text-slate-400">Bandwidth</dt>
357	            <dd>{server.plan.bandwidthTB} TB / month</dd>
358	          </div>
359	          <div className="flex justify-between">
360	            <dt className="text-slate-400">Operating system</dt>
361	            <dd>{server.osTemplate.name}</dd>
362	          </div>
363	          <div className="flex justify-between">
364	            <dt className="text-slate-400">Created</dt>
365	            <dd>{server.createdAt.toISOString().slice(0, 10)}</dd>
366	          </div>
367	          <div className="flex justify-between">
368	            <dt className="text-slate-400">{server.isFree ? "Billing" : "Renews"}</dt>
369	            <dd>
370	              {server.isFree
371	                ? "Free — never expires"
372	                : server.expiresAt
373	                  ? server.expiresAt.toISOString().slice(0, 10)
374	                  : "—"}
375	            </dd>
376	          </div>
377	        </dl>
378	      </div>
379	
380	      {!server.isFree ? (
381	        // The "Price /mo" the card shows must agree with what Renew now charges.
382	        // A game server is sold at its game plan's flat price, so its monthly
383	        // run-rate is that price over its term — NOT the base VPS plan.priceCents
384	        // it is built on, which would read $8.99/mo beside a $4.99 renewal on the
385	        // same card. Both figures derive from renewQuote, the single shared
386	        // formula, and extra disk mirrors renewalCharge (game plans carry no
387	        // add-on line, so showing one would overstate the monthly).
388	        <RenewalCard
389	          serverId={server.id}
390	          autoRenew={server.autoRenew}
391	          expiresAt={server.expiresAt ? server.expiresAt.toISOString() : null}
392	          priceCents={
393	            server.gamePlan
394	              ? Math.round(renewQuote.totalCents / renewQuote.months)
395	              : server.plan.priceCents
396	          }
397	          extraDiskGB={server.extraDiskGB}
398	          extraDiskMonthlyCents={server.gamePlan ? 0 : extraDiskCentsAt(server.extraDiskGB, extraDiskPriceCents)}
399	          suspendedUnpaid={server.status === "SUSPENDED" && !!server.suspendedNote?.includes("unpaid")}
400	          renewTotalCents={renewQuote.totalCents}
401	          renewDurationLabel={renewQuote.durationLabel}
402	        />
403	      ) : (
404	        <div className="card">
405	          <h2 className="mb-3 font-semibold">Subscription</h2>
406	          <p className="text-sm text-slate-400">
407	            This server is free of charge — no billing, no expiry.
408	          </p>
409	        </div>
410	      )}
411	
412	      {!server.isFree && server.status !== "DELETING" && (
413	        <div className="card md:col-span-2">
414	          <CancelService
415	            serverId={server.id}
416	            hostname={server.hostname}
417	            expiresAt={server.expiresAt ? server.expiresAt.toISOString() : null}
418	            autoRenew={server.autoRenew}
419	            refundEstimateCents={terminationRefundCents({
420	              isFree: server.isFree,
421	              expiresAt: server.expiresAt,
422	              isGame: !!server.gamePlanId,
423	              planMonthlyCents: server.plan.priceCents,
424	              termMonths: server.termMonths,
425	              termPromoPercent: server.termPromoPercent,
426	              refundableTermCents: server.refundableTermCents,
427	              annualDiscountPct: frozenAnnualDiscountPct(server) ?? annualPct,
428	            })}
429	          />
430	        </div>
431	      )}
432	
433	      <div className="card md:col-span-2">
434	        <h2 className="mb-4 font-semibold">Disk usage</h2>
435	        <DiskUsageChart
436	          serverId={server.id}
437	          planTotalGB={totalDiskGB}
438	          available={!!server.vmid && steady}
439	        />
440	      </div>
441	
442	      <div className="card md:col-span-2">
443	        <h2 className="mb-3 font-semibold">Project</h2>
444	        <ProjectAssign
445	          serverId={server.id}
446	          currentProjectId={server.projectId}
447	          projects={projects.map((p) => ({ id: p.id, name: p.name, color: p.color }))}
448	        />
449	      </div>
450	    </div>
451	  );
452	
453	  /* ---------- Tab: Files ---------- */
454	  const filesPanel =
455	    server.status === "RUNNING" ? (
456	      <FileManager serverId={server.id} />
