465	      </div>
466	    );
467	
468	  /* ---------- Tab: Snapshots ---------- */
469	  const snapshotsTab = (
470	    <div className="space-y-6">
471	      <div className="card">
472	        <h2 className="mb-4 font-semibold">Create snapshot</h2>
473	        <CreateSnapshotForm serverId={server.id} disabled={busy || !steady} />
