1	// Single fulfilment path for a paid Stripe Checkout session, shared by BOTH the
2	// success-redirect route and the webhook. Plain server module (not "use server").
3	//
4	// WHY THIS EXISTS (2026-07-25)
5	// Fulfilment used to live in `app/api/stripe/confirm/route.ts` and was gated on
6	// whether `creditCheckoutSession()` returned true. That boolean is true only for
7	// the caller that won the race to insert the wallet credit — and the webhook
8	// calls the same function and discards the result. So:
9	//
10	//   * Race: the webhook's insert lands first, the confirm request gets P2002,
11	//     `credited === false`, and the redirect quietly lands on an empty page.
12	//     $249 charged, $249 credited, no server, no error, no notification.
13	//   * Deterministic: the customer closes the tab before `success_url` resolves,
14	//     so the confirm route never runs at all. Same outcome, 100% reproducible.
15	//
16	// Stripe's own guidance is explicit that a browser redirect must not be the
17	// fulfilment trigger. Now BOTH callers run this, and a `FulfilledSession` row —
18	// its own marker, not a side effect of crediting — decides the single winner.
19	
20	import type Stripe from "stripe";
21	import { db } from "./db";
22	import {
23	  classifyCheckoutSession,
24	  creditCheckoutSession,
25	  retrieveCheckoutSession,
26	  isPurchaseLegSession,
27	  packMetadata,
28	  STRIPE_METADATA_VALUE_MAX,
29	  type CheckoutPurpose,
30	} from "./stripe";
31	import { saveCardFromPaymentSession } from "./stripe-cards";
32	import { placeOrder } from "./order";
33	import { placeGameOrder } from "./game-order";
34	import { placeHostingCardOrder } from "./actions-hosting";
35	import { placeEmailCardOrder } from "./actions-email-hosting";
36	import { applyResize } from "./resize";
37	import { applyDiskExpand } from "./disk-expand";
38	import { recordDeployFunnelError } from "./deploy-funnel";
39	import { sendMetaConversion } from "./tracking";
40	import { cookies, headers } from "next/headers";
41	
42	/**
43	 * Which rail actually moved the money. Stripe is the only one with a real
44	 * Checkout Session (so `saveCardFromPaymentSession` and the Stripe-specific
45	 * ledger label only ever run for it); PayPal and Coinbase Commerce reach this
46	 * same dispatch through `fulfilExternalPayment` below with a SYNTHETIC
47	 * session-shaped object carrying the identical nxeon* metadata keys.
48	 */
49	export type PaymentProvider = "stripe" | "paypal" | "coinbase";
50	
51	export type FulfilResult = {
52	  /** Where the browser should end up. The webhook ignores this. */
53	  redirect: string;
54	  /** True when THIS call performed the fulfilment work. */
55	  fulfilled: boolean;
56	  kind: "order" | "gameOrder" | "hostOrder" | "emailOrder" | "resize" | "diskExpand" | "topup" | "none";
57	  error?: string;
58	};
59	
60	/**
61	 * Claim exclusive responsibility for fulfilling `sessionId`.
62	 * Returns false when another caller already holds the claim — the UNIQUE index,
63	 * not a read-then-write check, is what makes this safe under concurrency.
64	 */
65	async function claim(sessionId: string, kind: string): Promise<boolean> {
66	  try {
67	    await db.fulfilledSession.create({ data: { stripeSessionId: sessionId, kind } });
68	    return true;
69	  } catch (e) {
70	    if ((e as { code?: string })?.code === "P2002") return false; // someone else has it
71	    throw e;
72	  }
73	}
74	
75	async function settle(sessionId: string, status: "DONE" | "FAILED", detail?: string) {
76	  await db.fulfilledSession
77	    .update({ where: { stripeSessionId: sessionId }, data: { status, detail: detail?.slice(0, 500) } })
78	    .catch(() => {});
79	}
80	
81	/**
82	 * Tell the customer their money is safe and someone knows. Called only on a path
83	 * where the card HAS cleared and fulfilment did not happen, so silence is the one
84	 * outcome that is never acceptable.
85	 */
86	async function notifyStalled(userId: string) {
87	  await db.notification
88	    .create({
89	      data: {
90	        userId,
91	        title: "Payment received — we couldn't finish setting up your server",
92	        body: "Your payment is safe and sitting in your wallet. Our team has been alerted; deploy again or contact support and we'll sort it out.",
93	        href: "/dashboard/billing",
94	      },
95	    })
96	    .catch(() => {});
97	}
98	
99	/**
100	 * Report a completed order as an ad-conversion, exactly once, on the WINNING fulfil
101	 * call (this only runs where `fulfilled === true`, so no double count under the
102	 * redirect/webhook race). Fires the server-side Meta Conversions API event — best
103	 * effort, inert unless the pixel id + CAPI token are set, and it never throws into
104	 * fulfilment — then returns the redirect tagged with the SAME event_id and the real
105	 * charged amount (`session.amount_total`, what Stripe actually took), so the browser
106	 * pixel (`PurchaseTracker`) can fire and Meta dedupes the pair into ONE conversion.
107	 * READ-ONLY on money: it reports the amount, it never changes a charge.
108	 */
109	async function reportPurchase(
110	  redirect: string,
111	  session: Awaited<ReturnType<typeof retrieveCheckoutSession>>,
112	  email?: string,
113	  userId?: string,
114	  /** Product kind for the per-funnel Google Ads conversion ("vps" | "game"). */
115	  prod?: string,
116	): Promise<string> {
117	  const value = typeof session.amount_total === "number" ? session.amount_total / 100 : 0;
118	  if (!(value > 0)) return redirect; // free / zero-charge order — nothing to report
119	  const currency = (session.currency ?? "usd").toUpperCase();
120	  // Best-effort match signals from the request: the Meta _fbc/_fbp cookies + UA/IP.
121	  // Wrapped so the webhook path (no browser request scope) simply sends without them.
122	  let fbc: string | undefined, fbp: string | undefined, userAgent: string | undefined, clientIp: string | undefined;
123	  try {
124	    const [ck, h] = await Promise.all([cookies(), headers()]);
125	    fbc = ck.get("_fbc")?.value || undefined;
126	    fbp = ck.get("_fbp")?.value || undefined;
127	    userAgent = h.get("user-agent") ?? undefined;
128	    clientIp = (h.get("x-forwarded-for")?.split(",")[0] ?? "").trim() || undefined;
129	  } catch {
130	    /* no request scope (webhook) — send without cookie/UA signals */
131	  }
132	  const { eventId } = await sendMetaConversion({
133	    eventName: "Purchase",
134	    email,
135	    value,
136	    currency,
137	    sourceUrl: redirect,
138	    fbc,
139	    fbp,
140	    userAgent,
141	    clientIp,
142	    externalId: userId,
143	  });
144	  // SERVER-SIDE Google Ads offline conversion for the paid order, using the captured
145	  // gclid — reliable where the browser gtag is not. Best-effort + idempotent (deduped
146	  // on the Stripe session id). Fires the product-specific action (vps/hosting/game/…)
147	  // AND a generic "purchase". Inert until the Ads API creds are configured.
148	  if (userId) {
149	    try {
150	      const { recordAdsConversion } = await import("./google-ads");
151	      const valueCents = Math.round(value * 100);
152	      if (prod) await recordAdsConversion({ kind: prod, userId, dedupeKey: `${prod}:${session.id}`, valueCents, currency });
153	      await recordAdsConversion({ kind: "purchase", userId, dedupeKey: `purchase:${session.id}`, valueCents, currency });
154	    } catch {
155	      /* tracking is best-effort — the order is already fulfilled */
156	    }
157	  }
158	  const params = new URLSearchParams({ purchase: "1", pv: value.toFixed(2), pc: currency, pe: eventId, ...(prod ? { prod } : {}) });
159	  return `${redirect}${redirect.includes("?") ? "&" : "?"}${params.toString()}`;
160	}
161	
162	/**
163	 * Credit the wallet and fulfil whatever the session was for, exactly once.
164	 * Safe to call repeatedly and concurrently from the redirect and the webhook.
165	 *
166	 * THROWS when Stripe cannot be read. That is deliberate and it is the fix for the
167	 * defect found on 2026-07-27: this function used to ask three helpers for the
168	 * session, each of which swallowed every error into `null`, so a transient Stripe
169	 * failure was indistinguishable from "no purchase metadata" and fell through to
170	 * the top-up branch below reporting `fulfilled: true`. A real order then had its
171	 * card charged with no server, no FulfilledSession row and no notification — and
172	 * because the webhook returns 200 either way, Stripe never retried it. A throw
173	 * lands the browser on `?pending=1` (see app/api/stripe/confirm) and puts the
174	 * failure in the webhook's log, which is loud; declaring it a top-up was silent.
175	 */
176	export async function fulfilCheckoutSession(sessionId: string, base = ""): Promise<FulfilResult> {
177	  // ONE retrieve, one view of the session, shared by the credit and the routing.
178	  const session = await retrieveCheckoutSession(sessionId);
179	  const purpose = classifyCheckoutSession(session);
180	  return runFulfilment(session, purpose, base, "stripe");
181	}
182	
183	/**
184	 * The actual dispatch, factored out of `fulfilCheckoutSession` so
185	 * `fulfilExternalPayment` (PayPal / Coinbase Commerce, below) can drive the exact
186	 * same claim/credit/provision/settle/notify logic from a SYNTHETIC session-shaped
187	 * object instead of a real Stripe retrieve. Nothing in this function's body
188	 * changed from the original `fulfilCheckoutSession` other than: (a) `sessionId` is
189	 * now read off `session.id` instead of being a separate parameter, and (b) the two
190	 * spots that are genuinely Stripe-only — crediting the wallet, and recording the
191	 * card for renewals — are gated on `provider === "stripe"`. Every claim/settle/
192	 * notify/provisioning line is untouched.
193	 */
194	async function runFulfilment(
195	  session: Stripe.Checkout.Session,
196	  purpose: CheckoutPurpose,
197	  base: string,
198	  provider: PaymentProvider,
199	): Promise<FulfilResult> {
200	  const sessionId = session.id;
201	
202	  // Nothing was paid (an abandoned session id, or one replayed before capture).
203	  // Never claim fulfilment for money that has not arrived.
204	  if (purpose.kind === "unpaid") {
205	    return { redirect: `${base}/dashboard/billing`, fulfilled: false, kind: "none" };
206	  }
207	
208	  // Crediting is separately idempotent (UNIQUE stripeSessionId on the wallet
209	  // transaction). We deliberately IGNORE its return value now — it reports who
210	  // won the credit race, which is not the same question as "has this been
211	  // fulfilled", and conflating the two was the bug. A THROW, however, is not a
212	  // race: the money has not reached the wallet, so nothing below may spend it.
213	  //
214	  // `creditCheckoutSession` itself is Stripe-specific (it types its argument as a
215	  // real `Stripe.Checkout.Session`); PayPal/Coinbase route through
216	  // `creditExternalPayment` instead, which writes the identical
217	  // WalletTransaction/User.balanceCents/notification shape but with an honest
218	  // ledger label (never "Stripe payment" for money PayPal or Coinbase moved) and
219	  // no invoice branch, since every external-payment kind reaching this function is
220	  // a purchase leg, never a bare top-up — see that function's doc comment.
221	  if (provider === "stripe") {
222	    await creditCheckoutSession(session);
223	  } else {
224	    await creditExternalPayment(session, provider);
225	  }
226	
227	  // Purchase metadata is present but cannot be trusted. Retrying will never fix
228	  // it, so claim the session and record the failure exactly like a failed order:
229	  // reconcilable, and the customer is told. What it must NEVER become is a silent
230	  // wallet top-up, which is precisely what the old `null` fall-through produced.
231	  if (purpose.kind === "unreadable") {
232	    if (await claim(sessionId, "unreadable")) {
233	      await settle(sessionId, "FAILED", purpose.detail);
234	      if (purpose.userId) await notifyStalled(purpose.userId);
235	    }
236	    return {
237	      redirect: `${base}/dashboard/billing?paid=1`,
238	      fulfilled: false,
239	      kind: "none",
240	      error: purpose.detail,
241	    };
242	  }
243	
244	  const order = purpose.kind === "order" ? purpose : null;
245	  if (order) {
246	    if (!(await claim(sessionId, "order"))) {
247	      return { redirect: `${base}/dashboard/servers`, fulfilled: false, kind: "order" };
248	    }
249	    try {
250	      const user = await db.user.findUnique({ where: { id: order.userId } });
251	      if (!user) throw new Error("user not found for paid order");
252	      // Settle the price stamped on the session BEFORE the card was charged — never
253	      // a fresh quote taken now. The customer has already paid the card leg of that
254	      // exact total; re-pricing here and taking the difference out of the wallet is
255	      // the H2 incident (see OrderPrice in lib/order.ts). This is the same shape as
256	      // the resize and disk-expand branches below, which have always passed the
257	      // amount through metadata for this reason.
258	      // No request-scoped IP on the fulfil path (this can run in the webhook), so the
259	      // per-IP cap can't be enforced here — the per-account unique still holds, and
260	      // the first-month-free HOLD was already reserved (per-account AND per-IP) before
261	      // the card was charged, so the double-claim race is closed regardless. Fulfilment
262	      // CONFIRMS that hold via `promoReservationToken` rather than contending for a
263	      // fresh claim. `campaign` rides in via metadata so attribution survives the card
264	      // round-trip even in the webhook (no cookies).
265	      const serverId = await placeOrder(user, order.intent, order.sold, {
266	        ipHash: null,
267	        campaign: order.campaign,
268	        promoReservationToken: order.promoReservationToken,
269	        // Same discipline as the promo hold: the coupon was RESERVED (per-person + global
270	        // cap) before the card was charged, and placeOrder CONFIRMS that hold via this
271	        // token rather than contending for a fresh claim — no double-claim, no over-charge.
272	        couponReservationToken: order.couponReservationToken,
273	      });
274	      await settle(sessionId, "DONE", serverId);
275	      // Record the card this order was paid with (the session set
276	      // setup_future_usage) so the renewal sweep can auto-charge it next cycle.
277	      // Guarded: the money moved and the server exists — card recording must never
278	      // turn a completed fulfilment into a failure.
279	      if (provider === "stripe") {
280	        try {
281	          await saveCardFromPaymentSession(session, order.userId);
282	        } catch {
283	          /* best-effort: fulfilment already succeeded */
284	        }
285	      }
286	      const redirect = await reportPurchase(`${base}/dashboard/servers/${serverId}`, session, user.email, user.id, "vps");
287	      return { redirect, fulfilled: true, kind: "order" };
288	    } catch (e) {
289	      // Payment is captured and the funds are in the wallet — record the failure
290	      // so it is reconcilable rather than invisible, and tell the customer.
291	      const msg = String((e as Error)?.message ?? e);
292	      await settle(sessionId, "FAILED", msg);
293	      await notifyStalled(order.userId);
294	      // Deploy-funnel: the card CLEARED but the order couldn't be placed — the one
295	      // payment-tail failure only visible server-side (the browser has left the
296	      // wizard, or this is the webhook). Recording it on the Payment step lets the
297	      // admin funnel tell "paid, then failed" from a plain abandon. Best-effort +
298	      // guarded so it never re-enters the money path we're unwinding.
299	      try {
300	        await recordDeployFunnelError({ product: "vps", step: "Payment", stepIndex: 7, errorCode: "PAID_ORDER_FAILED", errorMessage: msg, userId: order.userId });
301	      } catch {
302	        /* analytics must never disturb fulfilment */
303	      }
304	      return { redirect: `${base}/dashboard/deploy?paid=1`, fulfilled: false, kind: "order", error: msg };
305	    }
306	  }
307	
308	  // Game-server order — the game analogue of the `order` branch above. Same claim /
309	  // settle / notify discipline; the card leg was credited to the wallet by
310	  // `creditCheckoutSession` above, then `placeGameOrder` debits the SOLD total back
311	  // out — never a fresh quote taken now (the H2 re-pricing incident). Game carries
312	  // no promo/coupon hold, so there is nothing to confirm and no per-IP concern here.
313	  const gameOrder = purpose.kind === "gameOrder" ? purpose : null;
314	  if (gameOrder) {
315	    if (!(await claim(sessionId, "gameOrder"))) {
316	      return { redirect: `${base}/dashboard/servers`, fulfilled: false, kind: "gameOrder" };
317	    }
318	    try {
319	      const user = await db.user.findUnique({ where: { id: gameOrder.userId } });
320	      if (!user) throw new Error("user not found for paid game order");
321	      const serverId = await placeGameOrder(user, gameOrder.intent, gameOrder.sold);
322	      await settle(sessionId, "DONE", serverId);
323	      // Save the card for off-session renewals (same guard as the order branch).
324	      if (provider === "stripe") {
325	        try {
326	          await saveCardFromPaymentSession(session, gameOrder.userId);
327	        } catch {
328	          /* best-effort: fulfilment already succeeded */
329	        }
330	      }
331	      const redirect = await reportPurchase(`${base}/dashboard/servers/${serverId}`, session, user.email, user.id, "game");
332	      return { redirect, fulfilled: true, kind: "gameOrder" };
333	    } catch (e) {
334	      // Payment is captured and the funds are in the wallet — record the failure so
335	      // it is reconcilable rather than invisible, and tell the customer.
336	      const msg = String((e as Error)?.message ?? e);
337	      await settle(sessionId, "FAILED", msg);
338	      await notifyStalled(gameOrder.userId);
339	      // Deploy-funnel: card cleared but the game order couldn't be placed — the same
340	      // server-only payment-tail failure as the VPS branch above. Best-effort + guarded.
341	      try {
342	        await recordDeployFunnelError({ product: "game", step: "Payment", stepIndex: 4, errorCode: "PAID_ORDER_FAILED", errorMessage: msg, userId: gameOrder.userId });
343	      } catch {
344	        /* analytics must never disturb fulfilment */
345	      }
346	      return { redirect: `${base}/dashboard/games?paid=1`, fulfilled: false, kind: "gameOrder", error: msg };
347	    }
348	  }
349	
350	  // Shared-hosting order funded by card — the hosting analogue of the `order` branch.
351	  // The card leg was credited to the wallet by `creditCheckoutSession` above; then
352	  // `placeHostingCardOrder` re-verifies this same session server-side and runs the
353	  // audited wallet placement (`placeHostingOrderCore`), which DEBITS the wallet and
354	  // claims its own `hostorder:<key>` marker — so a webhook + redirect can't place two
355	  // accounts even before the FulfilledSession claim below. Same claim/settle/notify
356	  // discipline; card save is best-effort so it can never fail a completed order.
357	  const hostOrder = purpose.kind === "hostOrder" ? purpose : null;
358	  if (hostOrder) {
359	    if (!(await claim(sessionId, "hostOrder"))) {
360	      return { redirect: `${base}/dashboard/hosting`, fulfilled: false, kind: "hostOrder" };
361	    }
362	    try {
363	      const res = await placeHostingCardOrder(sessionId);
364	      if ("skip" in res) throw new Error("session did not classify as a hosting order");
365	      if (!("accountId" in res) || !res.accountId) {
366	        throw new Error(("error" in res && res.error) || "hosting order failed");
367	      }
368	      await settle(sessionId, "DONE", res.accountId);
369	      if (provider === "stripe") {
370	        try {
371	          await saveCardFromPaymentSession(session, hostOrder.userId);
372	        } catch {
373	          /* best-effort: fulfilment already succeeded */
374	        }
375	      }
376	      return { redirect: `${base}/dashboard/hosting/${res.accountId}`, fulfilled: true, kind: "hostOrder" };
377	    } catch (e) {
378	      const msg = String((e as Error)?.message ?? e);
379	      await settle(sessionId, "FAILED", msg);
380	      await notifyStalled(hostOrder.userId);
381	      try {
382	        await recordDeployFunnelError({ product: "hosting", step: "Payment", stepIndex: 7, errorCode: "PAID_ORDER_FAILED", errorMessage: msg, userId: hostOrder.userId });
383	      } catch {
384	        /* analytics must never disturb fulfilment */
385	      }
386	      return { redirect: `${base}/dashboard/deploy?paid=1`, fulfilled: false, kind: "hostOrder", error: msg };
387	    }
388	  }
389	
