508	/**
509	 * Credit the wallet for a paid PayPal/Coinbase Commerce session — the non-Stripe
510	 * analogue of `creditCheckoutSession` (lib/stripe.ts). Deliberately a SEPARATE,
511	 * smaller function rather than a call into that one, for two reasons:
512	 *
513	 *  1. Honesty of the ledger. `creditCheckoutSession` hard-codes the wallet-
514	 *     transaction description as `Stripe payment (${session.id})`. Reusing it for
515	 *     PayPal/Coinbase would label a customer's PayPal or crypto payment as a
516	 *     "Stripe payment" in their own billing history AND in the admin refund
517	 *     tool's ledger search (`lib/actions-admin-billing.ts`'s `description:
518	 *     {contains: "Stripe payment (cs_"}` — that regex's `cs_` prefix requirement
519	 *     means a synthetic `paypal:`/`coinbase:` id would never match it anyway, so
520	 *     nothing is UNSAFE, but the label would still be a plain false statement.
521	 *  2. Every external-payment session reaching this function was created by our
522	 *     own `lib/actions-payment-providers.ts` order/charge-creation actions, which
523	 *     never create one without purchase metadata (order/gameOrder/hostOrder/
524	 *     emailOrder) — there is no "top up your wallet with PayPal/crypto" product.
525	 *     So unlike `creditCheckoutSession`, there is no top-up invoice branch here;
526	 *     `isPurchaseLegSession` is asserted rather than branched on, and a session
527	 *     that somehow fails it is refused loudly rather than silently treated as a
528	 *     top-up (exactly the "unrecognised metadata → top-up" bug `packMetadata`'s
529	 *     doc comment and the `unreadable` classification exist to end — the failure
530	 *     mode this function must never reintroduce from a different code path).
531	 *
532	 * Idempotent the same way: UNIQUE(stripeSessionId) on `WalletTransaction`, so a
533	 * client-driven capture racing the provider's webhook is safe — P2002 means
534	 * someone else already credited this exact session id.
535	 */
536	async function creditExternalPayment(
537	  session: Stripe.Checkout.Session,
538	  provider: Exclude<PaymentProvider, "stripe">,
539	): Promise<boolean> {
540	  const userId = session.metadata?.nxeonUserId;
541	  const cents = session.amount_total ?? 0;
542	  if (!userId || cents <= 0 || session.payment_status !== "paid") return false;
543	
544	  if (!isPurchaseLegSession(session.metadata)) {
545	    throw new Error(
546	      `${provider} payment ${session.id} carries no recognised purchase metadata — refusing to treat unrecognised money as a top-up`,
547	    );
548	  }
549	
550	  const label = provider === "paypal" ? "PayPal" : "Coinbase Commerce";
551	  try {
552	    await db.$transaction([
553	      db.walletTransaction.create({
554	        data: {
555	          userId,
556	          amountCents: cents,
557	          description: `${label} payment (${session.id})`,
558	          stripeSessionId: session.id,
559	        },
560	      }),
561	      db.user.update({ where: { id: userId }, data: { balanceCents: { increment: cents } } }),
562	      db.notification.create({
563	        data: {
564	          userId,
565	          title: `Payment of $${(cents / 100).toFixed(2)} received`,
566	          href: "/dashboard/billing",
567	        },
568	      }),
569	    ]);
570	  } catch (e) {
571	    if ((e as { code?: string })?.code === "P2002") return false; // raced — already credited
572	    throw e;
573	  }
574	  // Best-effort side effects, same as creditCheckoutSession — never allowed to
575	  // turn a completed credit into a reported failure.
576	  try {
577	    const { maybeRewardReferral } = await import("./actions-growth");
578	    await maybeRewardReferral(userId);
579	  } catch {
580	    /* best-effort */
581	  }
582	  try {
583	    const u = await db.user.findUnique({ where: { id: userId } });
584	    if (u) {
585	      const { sendMail, emails } = await import("./mailer");
586	      const tpl = emails.receipt(`$${(cents / 100).toFixed(2)}`, "your Nxeon order", false);
587	      await sendMail({ to: u.email, subject: tpl.subject, html: tpl.html, userId, kind: "receipt" });
588	    }
589	  } catch {
590	    /* best-effort */
591	  }
592	  return true;
593	}
