595	export type ExternalPaymentInput = {
596	  provider: Exclude<PaymentProvider, "stripe">;
597	  /** PayPal's order id, or Coinbase Commerce's charge code — the provider's own reference. */
598	  externalId: string;
599	  /** The `PendingExternalPayment` row id created when the order/charge was opened
600	   *  (lib/actions-payment-providers.ts) — the ONE place the full order metadata lives. */
601	  pendingId: string;
602	  base?: string;
603	};
604	
605	/**
606	 * Fulfil a PAID PayPal order or Coinbase Commerce charge through the EXACT SAME
607	 * `runFulfilment` dispatch Stripe's `fulfilCheckoutSession` uses — the seam this
608	 * whole module exists to provide. Builds a SYNTHETIC `Stripe.Checkout.Session`-
609	 * shaped object from the `PendingExternalPayment` row (same nxeon* metadata keys,
610	 * `payment_status: "paid"`, the row's own server-computed `amountCents`) and hands
611	 * it to `runFulfilment` with `provider` set so the two Stripe-only steps above are
612	 * skipped. There is exactly ONE dispatch function in this codebase; this is how a
613	 * second payment rail reaches it without a second copy of the claim/settle/
614	 * provision/notify logic.
615	 *
616	 * Callers: the PayPal capture server action (client-driven, like Stripe's confirm
617	 * redirect) AND the PayPal webhook (the reliable backstop) — the SAME
618	 * confirm/webhook race Stripe already runs safely, because the claim below is the
619	 * same `FulfilledSession` UNIQUE(stripeSessionId) index, just keyed
620	 * `"paypal:<orderId>"` instead of a Stripe session id. Coinbase Commerce has no
621	 * client-driven capture step (crypto confirmation only ever arrives by webhook),
622	 * so its webhook is the only caller — still idempotent on its own if Coinbase ever
623	 * redelivers the event.
624	 *
625	 * THROWS if the `PendingExternalPayment` row cannot be found or its stored
626	 * metadata is not valid JSON — the same "throw rather than silently misclassify"
627	 * discipline `retrieveCheckoutSession` and `fulfilCheckoutSession` already apply
628	 * to a Stripe read failure. A row that cannot be trusted must never fall through
629	 * to the top-up branch.
630	 */
631	export async function fulfilExternalPayment(input: ExternalPaymentInput): Promise<FulfilResult> {
632	  const row = await db.pendingExternalPayment.findUnique({ where: { id: input.pendingId } });
633	  if (!row) {
634	    throw new Error(`No PendingExternalPayment row for id ${input.pendingId} (${input.provider} ${input.externalId})`);
635	  }
636	  if (row.provider !== input.provider) {
637	    throw new Error(
638	      `PendingExternalPayment ${input.pendingId} provider mismatch: expected ${input.provider}, stored ${row.provider}`,
639	    );
640	  }
641	
642	  let metadata: Record<string, string>;
643	  try {
644	    const parsed = JSON.parse(row.metadata);
645	    if (!parsed || typeof parsed !== "object") throw new Error("not an object");
646	    metadata = parsed as Record<string, string>;
647	  } catch {
648	    throw new Error(`PendingExternalPayment ${input.pendingId} metadata is not readable JSON`);
649	  }
650	
651	  // The provider-qualified id IS the FulfilledSession/WalletTransaction claim key —
652	  // "paypal:5O190127TN364715T" can never collide with a real Stripe `cs_...` id or
653	  // with the other provider's charge codes.
654	  const sessionId = `${input.provider}:${input.externalId}`;
655	  const synthetic = {
656	    id: sessionId,
657	    metadata,
658	    payment_status: "paid",
659	    amount_total: row.amountCents,
660	    currency: row.currency,
661	    customer: null,
662	    payment_intent: null,
663	  } as unknown as Stripe.Checkout.Session;
664	
665	  const purpose = classifyCheckoutSession(synthetic);
666	
667	  try {
668	    const result = await runFulfilment(synthetic, purpose, input.base ?? "", input.provider);
669	    await db.pendingExternalPayment
670	      .update({ where: { id: row.id }, data: { status: "PAID", providerRef: input.externalId } })
671	      .catch(() => {});
672	    return result;
673	  } catch (e) {
674	    await db.pendingExternalPayment.update({ where: { id: row.id }, data: { status: "FAILED" } }).catch(() => {});
675	    throw e;
676	  }
677	}
