3	import { useEffect, useRef, useState } from "react";
4	import { useRouter } from "next/navigation";
5	
6	/**
7	 * Client-side auto-refresh for the public /status page.
8	 *
9	 * The page copy promises component states refresh "roughly every 15 seconds",
10	 * but the page is a server component with no client polling — so until now that
11	 * sentence was aspirational. This calls `router.refresh()` on the interval,
12	 * which re-runs the (force-dynamic) server component and swaps in fresh,
13	 * already-sanitized markup. It fetches NO data itself, so there is no public
14	 * JSON surface to leak internals through — the server page stays the only place
15	 * health is read, and it already shows friendly names only.
16	 *
17	 * Pauses while the tab is hidden and resumes — with an immediate refresh — when
18	 * it becomes visible again.
19	 */
20	export function AutoRefresh({ intervalMs = 15_000 }: { intervalMs?: number }) {
21	  const router = useRouter();
22	  const [refreshing, setRefreshing] = useState(false);
23	  const timer = useRef<ReturnType<typeof setInterval> | null>(null);
24	
25	  useEffect(() => {
26	    const tick = () => {
27	      if (document.visibilityState !== "visible") return;
28	      setRefreshing(true);
29	      router.refresh();
30	      window.setTimeout(() => setRefreshing(false), 800);
31	    };
32	
33	    const start = () => {
34	      if (timer.current) return;
35	      timer.current = setInterval(tick, intervalMs);
36	    };
37	    const stop = () => {
38	      if (timer.current) {
39	        clearInterval(timer.current);
40	        timer.current = null;
41	      }
42	    };
43	
44	    const onVisibility = () => {
45	      if (document.visibilityState === "visible") {
46	        tick();
47	        start();
48	      } else {
49	        stop();
50	      }
51	    };
52	
53	    start();
54	    document.addEventListener("visibilitychange", onVisibility);
55	    return () => {
56	      stop();
57	      document.removeEventListener("visibilitychange", onVisibility);
58	    };
59	  }, [router, intervalMs]);
60	
61	  return (
62	    <span className="inline-flex items-center gap-1.5 text-xs text-slate-500">
63	      <span
64	        className={`h-1.5 w-1.5 rounded-full ${
65	          refreshing ? "bg-brand-400 animate-pulse-dot" : "bg-slate-600"
66	        }`}
67	      />
68	      Auto-refreshing
69	    </span>
70	  );
71	}
