413	async function provision(job: Job) {
414	  const server = await loadServer(job);
415	  // Clear any stale failure reason from a previous attempt as this run starts, so
416	  // a successful retry doesn't leave the last error hanging around on the row.
417	  await db.server.update({ where: { id: server.id }, data: { status: "PROVISIONING", provisionError: null } });
418	
419	  if (SANDBOX) {
420	    // Simulate provisioning entirely via DB writes — no Proxmox clone/config/
421	    // resize/start, no IPAM/OVH allocation, no cloud-init snippet write.
422	    const vmid = server.vmid ?? (990000 + (await db.server.count()));
423	    const password = generatePassword();
424	    const ip = sandboxIp(vmid);
425	    await db.server.update({
426	      where: { id: server.id },
427	      data: { vmid, ipAddress: ip, sshPort: null, rootPassword: null, rootPasswordEnc: encryptSecret(password), status: "RUNNING" },
428	    });
429	    await notify(
430	      server.userId,
431	      `Server ${server.hostname} is ready`,
432	      `Sandbox server provisioned (no real VM was created). ssh root@${ip}`,
433	      `/dashboard/servers/${server.id}`
434	    );
435	    // Post-purchase review request (once per server, skipped if no profiles set).
436	    await sendReviewRequestForServer(server.id);
437	    return;
438	  }
439	
440	  const { conn, row: nodeRow } = await nodeFor(server);
441	  const storage = server.plan.storageTier === "hdd"
442	    ? nodeRow?.storageHdd ?? "vmdata-hdd"
443	    : nodeRow?.storageNvme ?? "vmdata";
