"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import { useRouter } from "next/navigation";
import { createBackup, getBackupJob, type BackupJobStatus } from "@/lib/actions-server";

const POLL_MS = 2500;
/** A terminal (DONE/FAILED) job is only "fresh" enough to surface on load for a
 *  short window — avoids nagging about an ancient failure on every page visit. */
const FRESH_MS = 15 * 60 * 1000;

function isInFlight(j: BackupJobStatus | null): j is BackupJobStatus {
  return !!j && (j.status === "QUEUED" || j.status === "RUNNING");
}

function verbFor(type: BackupJobStatus["type"]): string {
  return type === "BACKUP_RESTORE" ? "Restore" : "Backup";
}

/**
 * Create-backup button + LIVE progress bar. Owns polling of the current
 * backup/restore job (`getBackupJob`) so it renders a themed bar with the live
 * percentage + step while a job is QUEUED/RUNNING, shows a "Backup failed —
 * server unaffected" note on failure, and refreshes the backups list on success.
 * Restores (enqueued elsewhere) surface here too since the poll covers both types.
 */
export function CreateBackupButton({
  serverId,
  disabled,
  initialJob = null,
}: {
  serverId: string;
  disabled?: boolean;
  initialJob?: BackupJobStatus | null;
}) {
  const router = useRouter();
  const [job, setJob] = useState<BackupJobStatus | null>(initialJob);
  const [error, setError] = useState<string | null>(null);
  const [queueing, setQueueing] = useState(false);
  const [dismissed, setDismissed] = useState<string | null>(null);

  // Ids we've observed in-flight this mount + the last status per id, so we can
  // detect an in-flight → DONE transition and refresh the list exactly once.
  const watched = useRef<Set<string>>(new Set());
  const lastStatus = useRef<Record<string, string>>({});

  const fetchJob = useCallback(async () => {
    try {
      const j = await getBackupJob(serverId);
      if (isInFlight(j)) watched.current.add(j.id);
      if (j) {
        const prev = lastStatus.current[j.id];
        // In-flight → DONE: the archive now exists, reload the backups table.
        if (prev && prev !== j.status && j.status === "DONE" && watched.current.has(j.id)) {
          router.refresh();
        }
        lastStatus.current[j.id] = j.status;
      }
      setJob(j);
    } catch {
      /* transient — keep last known state, next tick retries */
    }
  }, [serverId, router]);

  useEffect(() => {
    let cancelled = false;
    let timer: ReturnType<typeof setTimeout>;
    async function loop() {
      if (cancelled) return;
      await fetchJob();
      if (!cancelled) timer = setTimeout(loop, POLL_MS);
    }
    loop();
    return () => {
      cancelled = true;
      clearTimeout(timer);
    };
  }, [fetchJob]);

  const inFlight = isInFlight(job);
  const busy = queueing || inFlight;

  // Terminal notes only for jobs we watched in-flight OR that are recent.
  const relevant =
    !!job &&
    (watched.current.has(job.id) || Date.now() - new Date(job.createdAt).getTime() < FRESH_MS);
  const showFailed = !!job && job.status === "FAILED" && relevant && dismissed !== job.id;

  const pct = job?.progress ?? 0;
  const verb = job ? verbFor(job.type) : "Backup";

